TLM.f("Tempora/Pasc7-3",{"officium":"Feria Quarta Quattuor Temporum Pentecostes","rule":["LectioL1","no Gloria","Sequentia","Suffr=Ecclesiæ;Papa;;","Credo","Prefatio=Spiritu=hodierna die;"],"ruleInherited":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"fallback":"Tempora/Pasc7-0","sections":{"Introitus":[{"k":"ref","la":"Ps 67:8 67:9"},{"k":"text","la":"Deus, dum egrederéris coram pópulo tuo, iter fáciens eis, hábitans in illis, allelúja: terra mota est, cœli distillavérunt, allelúja, allelúja."},{"k":"ref","la":"Ps. 67:2"},{"k":"text","la":"Exsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Deus, dum egrederéris coram pópulo tuo, iter fáciens eis, hábitans in illis, allelúja: terra mota est, cœli distillavérunt, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Mentes nostras, quǽsumus, Dómine, Paráclitus, qui a te procédit, illúminet: et indúcat in omnem, sicut tuus promísit Fílius, veritátem:"},{"k":"macro","name":"Qui tecum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Acts 5:12-16"},{"k":"text","la":"In diébus illis: Per manus autem Apostolórum fiébant signa et prodígia multa in plebe. Et erant unanímiter omnes in pórticu Salomónis. Ceterórum autem nemo audébat se conjúngere illis: sed magnificábat eos pópulus. Magis autem augebátur credéntium in Dómino multitúdo virórum ac mulíerum, ita ut in pláteas ejícerent infírmos, et pónerent in léctulis ac grabátis, ut, veniénte Petro, saltem umbra illíus obumbráret quemquam illórum, et liberaréntur ab infirmitátibus suis. Concurrébat autem et multitúdo vicinárum civitátum Jerúsalem, afferéntes ægros et vexátos a spirítibus immúndis: qui curabántur omnes."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"(Hic genuflectitur) Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 6:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis Judæórum: Nemo potest veníre ad me, nisi Pater, qui misit me, tráxerit eum: et ego resuscitábo eum in novíssimo die. Est scriptum in Prophétis: Et erunt omnes docíbiles Dei. Omnis, qui audívit a Patre et dídicit, venit ad me. Non quia Patrem vidit quisquam, nisi is, qui est a Deo, hic vidit Patrem. Amen, amen, dico vobis: qui credit in me, habet vitam ætérnam. Ego sum panis vitæ. Patres vestri manducavérunt manna in desérto, et mórtui sunt. Hic est panis de cœlo descéndens: ut, si quis ex ipso manducáverit, non moriátur. Ego sum panis vivus, qui de cœlo descéndi. Si quis manducáverit ex hoc pane, vivet in ætérnum: et panis, quem ego dabo, caro mea est pro mundi vita."}],"Offertorium":[{"k":"ref","la":"Ps 118:47-48"},{"k":"text","la":"Meditábor in mandátis tuis, quæ diléxi valde: et levábo manus meas ad mandáta tua, quæ diléxi, allelúja."}],"Secreta":[{"k":"text","la":"Accipe, quǽsumus, Dómine, munus oblátum: et dignánter operáre; ut, quod mystériis ágimus, piis efféctibus celebrámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 14:27"},{"k":"text","la":"Pacem relínquo vobis, allelúja: pacem meam do vobis, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Suméntes, Dómine, cœléstia sacraménta, quǽsumus cleméntiam tuam: ut quod temporáliter gérimus ætérnis gáudiis consequámur"},{"k":"macro","name":"Per Dominum"}],"LectioL1":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Act 2:14-21"},{"k":"text","la":"In diébus illis: Stans Petrus cum úndecim, levávit vocem suam, et locútus est eis: Viri Judǽi, et qui habitátis Jerúsalem univérsi, hoc vobis notum sit, et áuribus percípite verba mea. Non enim, sicut vos æstimátis, hi ébrii sunt, cum sit hora diéi tértia: sed hoc est, quod dictum est per Prophétam Joël: Et erit in novíssimis diébus - dicit Dóminus - effúndam de Spíritu meo super omnem carnem, et prophetábunt fílii vestri et fíliæ vestræ, et júvenes vestri visiónes vidébunt, et senióres vestri sómnia somniábunt. Et quidem super servos meos et super ancíllas meas in diébus illis effúndam de Spíritu meo, et prophetábunt: et dabo prodígia in cœlo sursum et signa in terra deórsum, sánguinem et ignem et vapórem fumi. Sol convertétur in ténebras et luna in sánguinem, antequam véniat dies Dómini magnus et maniféstus. Et erit: omnis, quicúmque invocáverit nomen Dómini, salvus erit."},{"k":"macro","name":"Deo gratias"}],"GradualeL1":[{"k":"text","la":"Alleluia."},{"k":"ref","la":"Ps 32:6"},{"k":"text","la":"Verbo Dómini cœli firmáti sunt, et Spíritu oris ejus omnis virtus eórum."}],"OratioL1":[{"k":"text","la":"Præsta, quǽsumus, omnípotens et miséricors Deus: ut Spíritus Sanctus advéniens, templum nos glóriæ suæ dignánter inhabitándo perfíciat."},{"k":"macro","name":"Per Dominum eiusdem"}]},"hr":{"f05f2285270c7a79":{"t":"Ps 67, 8 i 9; Ps 67, 2\n(Ps 67, 8 i 9) Bože, kad si išao pred svojim narodom, pokazujući mu put, stanujući s njime, <i>aleluja</i>,\nzemlja se tresla i nebo se rastapalo, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 67, 2) Nek' ustane Bog i nek' se rasprše neprijatelji njegovi i neka pobjegnu od njegova lica koji mrze na nj.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 67, 8 i 9) Bože, kad si išao pred svojim narodom, pokazujući mu put, stanujući s njime, <i>aleluja</i>,\nzemlja se tresla i nebo se rastapalo, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 67, 8, 9). Bože, kad si išao pred narodom svojim, kad si išao preko pustinje, aleluja, zemlja se tresla i nebo se rastapalo, aleluja, aleluja. (Ps. 67, 2) Nek ustane Bog i nek se rasprše neprijatelji njegovi i neka pobjegnu od lica njegova, koji mrze na nj. Slava Ocu... Bože... ^ Iza »Gospodine smiiuj se« siijedi »Ponioiimo se«, bez »Prij^nite koljena«.","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"},"df669641fc3ba3d8":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da Utješitelj koji od tebe izlazi prosvijetli naše duše i uvede nas u svaku istinu kako je to obećao tvoj Sin.\n<i>Koji s Tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da Utješitelj, koji od Tebe izlazi, prosvijetli duše naše i uvede nas u svaku istinu, kako je to obećao Sin Tvoj, koji s Tobom... u jedinstvu istoga Duha...","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"},"0f5085641b8dfdbe":{"t":"Dj 2, 14-21\nČitanje Djela apostolskih. U one dane stade Petar s jedanaestoricom i podiže glas svoj i reče: Židovi i vi svi koji stanujete u Jeruzalemu! Ovo neka vam bude na znanje i poslušajte pozorno riječi moje! Nisu ovi pijani, kako vi mislite, jer je istom treća ura dana, nego je ovo što je kazao prorok Joel: I bit će u posljednje dane, govori Gospodin: Izlit ću od Duha svoga na svako tijelo i prorokovat će sinovi vaši i kćeri vaše i mladići će vaši vidjeti viđenje i starci će vaši sanjati sne. Pače: na sluge ću svoje i na službenice svoje u one dane izliti Duha svoga i prorokovat će. I dat ću čudesa gore na nebu i znakove dolje na zemlji: krv i oganj i oblake dima. Sunce će se pretvoriti u tamu i mjesec u krv prije nego dođe dan Gospodnji veliki i slavni. I svaki će se spasiti koji prizove ime Gospodnje.","kn":"Čitanje Djela Apostolskih (2, 14-21). U ome dane stade Petar s jedanaestoricom i podiže glas svoj i reče: Židovi i vi svi, koji stanujete u Jeruzalemu! Ovo neka vam bude na znanje i poslušajte pozorno riječi moje! Nisu ovi pijani, kako vi mislite, jer je istom trećaura dana; nego je ovo, što je ka.zao prorok Joel: I bit će u posljednje dane, govori Gospodin: Izllt ču od Duha .svoga na svako tijelo, i prorokovat će sinovi vaši i kćeri vaše, i mladići će vaši vidjeti viđenje, i starci će vaši sanjati sne. Pače: na sluge ču svoje i na službenice svoje u one dane izliti od Duha svoga i prorokovat će. I dat ču čudesa gore na nebu i znakove dolje n.a zemlji: krv i Oganj i oblake dima. Sunce će se pretvoriti u i tamu i mjesec u krv. prije nego dođe dan Gospod- I nji veliki i slavni. I svaki će se i^asiti, koji prizove ime Gospodnje.","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"},"eebb4afc0e772177":{"t":"Ps 32, 6\n<i>Aleluja</i>.\nAleluja. Riječju su Gospodnjom utvrđena nebesa i Duhom usta njegovih sav ukras njihov.","kn":"Aleluja (Ps. 32. 6). Riječju su Gospodnjom utvrđena nebesa i Duhom ustiju njegovih sav ukras njihov.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"9153cf763e439f0d":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući milosrdni Bože, da dođe Duh Sveti k nama i udostoji se od nas po svojem stanovanju učiniti hram slave svoje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući i milosrdni Bože, da se Duh Sveti, k nama dolazeći, dostoji od j nas po svojem stanovanju učiniti hram slave svoje, 1 po G. n. . . . u jedinstvu istoga ... .","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"53d0060df7f8aa53":{"t":"Dj 5, 12-16\nČitanje Djela apostolskih. U one su dane apostoli činili mnoge znakove i čudesa među narodom. I bijahu jednodušno svi u trijemu Salamonovu. A od ostalih se nije nitko usudio pridružiti k njima, samo ih je narod veličao. I sve se više umnožavao broj muževa i žena koji su vjerovali u Gospodina, tako te su na ulice iznosili bolesnike i stavljali ih na postelje i nosila da bi, kad Petar dođe, barem sjena njegova osjenila koga od njih. A skupljalo se mnoštvo iz okolnih gradova u Jeruzalem donoseći bolesnike i opsjednute od nečistih duhova i svi su ozdravljati.","kn":"Čitanje Djela Apostolskih (5, 12t16). U one su dane apostoli činili mnoge znake i čudesa među narodom. I bijahu jednodušno svi u trijemu Salampnovu. A od ostalih se nije nitko usudio pridružiti k njima, samo ih je narod veličao. I sve se više umnožavalo društvo muževa i žena, koji su vjerovali u Gospodina, tako, te su na ulice iznosili bolesnike i stavljali ih na postelje i nosila, da bi, kad Petar dođe, barem sjena njegova osjenila koga od njih. A skupljalo se mnoštvo iz okolnih gradova u Jeruzalem, donoseći bolesnike i opsjednute od nečistih duhova, i svi su ozdravili.","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"},"39bccb148e5b94ad":{"t":"<i>Aleluja</i>, <i>aleluja</i>.\n[Ovdje se poklekne] Dođi, Duše Sveti, i napuni srca svojih vjernih i zapali u njima oganj svoje ljubavi.","kn":"Aleluja, aleluja,. (Ovdje se poklekne.) .Dođi Duše Sveti i napuni srca svojih vjernih i zapali u njima oganj ljubavi svoje.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"8986d237bd5894a0":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"0141ee6a6e293766":{"t":"Iv 6, 44-52\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus mnoštvu židovskomu: Nitko ne može doći k meni, ako ga Otac, koji me je poslao, ne povuče. A ja ću ga uskrsnuti na sudnji dan. U prorocima stoji pisano: I bit će svi poučeni od Boga. Svaki koji je čuo Oca i naučio, dolazi k meni. Nitko nije vidio Oca, osim onoga koji je kod Boga, on je vidio Oca. Zaista, zaista vam kažem: Tko vjeruje u mene, ima život vječni. Ja sam kruh života. Oci su vaši jeli manu u pustinji i pomrli su. Ovo je kruh koji s neba silazi da tko od njega jede ne umre. Ja sam kruh živi koji sam s neba sišao. Ako tko jede od ovoga kruha, živjet će dovijeka. I kruh koji ću ja dati tijelo je moje za život svijeta.","kn":"t Slijedi sv. evanđelje po Ivanu (6, 44-62). U ono vrijeme reče Isus mnoštvu židovskomu: Nitko ne može doći k meni, ako ga Otac, koji me je poslao, ne povuče; i ja ću ga uskrsnuli na sudnji dan. U prorocima stoji pisano; I bit će svi poučeni od Boga.i Svaki, koji je čuo Oca, i naučio, dolazi k meni. Ne, da je itko vidio Oca, osim onoga, koji je kod Boga, on je vidio Oca. Zaista, zaista vam kažem: Tko vjeruje u mene, ima život vječni. Ja sam kruh života. Oci su vaši jeli manu u pustinji i pomrli su. Ovo je kruh, koji s neba silazi, da tko od njega jede, ne umre. Ja sam kruh živi, KOji sam s neba sišaO'. Ako tko jede od ovoga kruha, živjet će dovijeka; i kruh, koji ću ja dati, tijelo je moje za život svijetao","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"d23d6e7d3d78596a":{"t":"Ps 118, 47-48\nRazmišljam o tvojim zapovijedima koje veoma ljubim i uzdižem ruke svoje k tvojim zapovijedima koje ljubim, <i>aleluja</i>.","kn":"(Ps. 118, 47, 48). Razmišljam^ o zapovijedima Tvojim, koje veoma ljubim i uzdižem ruke svoje k zapovijedima Tvojim, koje ljubim, aleluja.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"a7647e61228b33a4":{"t":"Primi, molimo, Gospodine, prikazani dar i dopusti da pobožnim osjećajima slavimo što u otajstvu vršimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo. Gospodine, prikazani dar i dopusti, da svetkujemo učinke onoga, što pobožnom tajnom činimo, po G. n.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:"},"07a95622096299f7":{"t":"Iv 14, 27\nMir vam ostavljam, <i>aleluja</i>,\nmir svoj dajem vama, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 14, 27). Mir vam ostavljam, aleluja, mir svoj dajem vama, aleluja, aleluja.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"70c43c5cff134605":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, nebeske tajne, molimo tvoju dobrotu da vječnom radošću dostignemo ono što u vremenu činimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, nebeske tajne, molimo Tvoju dobrotu, da vječnom radošću dostignemo ono, što u vremenu činimo, po G. n.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"}}});
